    example: 'resource "azurerm_recovery_services_vault" "main" {\n  name                = "rsv-app-dev"\n  resource_group_name = azurerm_resource_group.main.name\n  location            = azurerm_resource_group.main.location\n  sku                 = "Standard"\n  storage_mode_type   = "GeoRedundant"\n}',
