// Learn Azure Landing Zones: governance concepts mapped to the Terraform resources that implement them.
const LZ_TOPICS = [
  { t: 'Azure Landing Zone', concept: 'A pre-configured environment of management groups, subscriptions, policies, identity, networking and monitoring that workloads "land" into.', purpose: 'Teams get subscriptions quickly, already governed, connected and monitored.', arch: 'Platform landing zones (management, connectivity, identity) serve application landing zones (corp, online).', tf: 'azurerm_management_group, policy assignments, azurerm_role_assignment, hub networking, Log Analytics. Microsoft also publishes the Azure Verified Module avm-ptn-alz for the full reference design.', example: 'Tenant Root Group\n└── contoso\n    ├── platform (management, connectivity, identity)\n    ├── landingzones (corp, online)\n    ├── sandbox\n    └── decommissioned', mistakes: ['Building workloads first and retrofitting governance later.', 'Copying the reference design without deciding what you actually need.'], ms: MS + 'cloud-adoption-framework/ready/landing-zone/', reg: ['azurerm_management_group'] },
  { t: 'Management Groups', concept: 'Containers above subscriptions that form a hierarchy under the Tenant Root Group.', purpose: 'Apply policy, RBAC and cost governance once to many subscriptions.', arch: 'Up to six levels below the root. A subscription is in exactly one management group.', tf: 'azurerm_management_group with parent_management_group_id; azurerm_management_group_subscription_association to place subscriptions.', example: 'resource "azurerm_management_group" "corp" {\n  name                       = "contoso-corp"\n  parent_management_group_id = azurerm_management_group.landingzones.id\n}', mistakes: ['Organising by department instead of by governance need.', 'Assigning everything at the Tenant Root Group.'], ms: MS + 'governance/management-groups/overview', reg: ['azurerm_management_group', 'azurerm_management_group_subscription_association'] },
  { t: 'Subscriptions', concept: 'The unit of billing, scale limits and a natural isolation boundary.', purpose: 'Separate environments, teams and platform functions, each with its own quotas and access.', arch: 'Enterprise designs use a subscription per workload and environment, plus platform subscriptions for connectivity, management and identity.', tf: 'azurerm_subscription (alias) to create, provider aliases with subscription_id to deploy into several at once.', example: 'provider "azurerm" {\n  alias           = "connectivity"\n  subscription_id = var.connectivity_subscription_id\n  features {}\n}', mistakes: ['One giant subscription for everything.', 'Creating subscriptions by hand so they miss the management group and policies.'], ms: MS + 'cloud-adoption-framework/ready/landing-zone/design-area/resource-org-subscriptions', reg: ['azurerm_subscription'] },
  { t: 'Resource Groups', concept: 'Lifecycle containers inside a subscription.', purpose: 'Deploy, secure and delete related resources together.', arch: 'Group by lifecycle and ownership: shared networking, application, data, operations.', tf: 'azurerm_resource_group, referenced by every resource\'s resource_group_name.', example: 'resource "azurerm_resource_group" "network" {\n  name     = "rg-app-prod-network"\n  location = "southeastasia"\n}', mistakes: ['Mixing resources with different lifecycles.', 'Granting Contributor at subscription scope when a resource group would do.'], ms: MS + 'azure-resource-manager/management/manage-resource-groups-portal', reg: ['azurerm_resource_group'] },
  { t: 'Azure Policy', concept: 'Rules evaluated on every create and update, and continuously for compliance.', purpose: 'Deny non-compliant deployments, audit drift and auto-remediate (modify or deploy if not exists).', arch: 'Definition (the rule) > initiative (a group of rules) > assignment (applied at a scope, inherited below).', tf: 'azurerm_policy_definition, azurerm_management_group_policy_set_definition, *_policy_assignment, data.azurerm_policy_definition_built_in.', example: 'data "azurerm_policy_definition_built_in" "allowed_locations" {\n  name = "e56962a6-4747-49cd-b67b-bf8b01975c4c"\n}', mistakes: ['Rolling out Deny without testing in DoNotEnforce mode first.', 'Forgetting the identity and role for Modify and DeployIfNotExists assignments.'], ms: MS + 'governance/policy/overview', reg: ['azurerm_policy_definition', 'azurerm_management_group_policy_assignment', 'azurerm_subscription_policy_assignment'] },
  { t: 'Role-Based Access Control', concept: 'Who can do what, where: a principal, a role definition and a scope.', purpose: 'Least privilege for people and workloads.', arch: 'Assignments inherit down the hierarchy. Prefer Entra groups and built-in roles; use PIM for privileged roles.', tf: 'azurerm_role_assignment, azurerm_role_definition for custom roles.', example: 'resource "azurerm_role_assignment" "readers" {\n  scope                = azurerm_management_group.root.id\n  role_definition_name = "Reader"\n  principal_id         = var.auditors_group_object_id\n}', mistakes: ['Standing Owner access for many people.', 'Custom roles with wildcard actions.'], ms: MS + 'role-based-access-control/overview', reg: ['azurerm_role_assignment', 'azurerm_role_definition'] },
  { t: 'Tags', concept: 'Name-value pairs on resources and resource groups.', purpose: 'Cost allocation, ownership, automation and policy targeting.', arch: 'Require tags on resource groups with policy, and inherit them onto resources with a Modify policy.', tf: 'tags = local.common_tags on every resource; the Require tag and Inherit tag built-in policies.', example: 'common_tags = {\n  Environment = var.environment\n  Owner       = "platform-team"\n}', mistakes: ['Inconsistent tag names (env, Env, Environment).', 'Relying on tags for security decisions.'], ms: MS + 'azure-resource-manager/management/tag-resources', reg: [] },
  { t: 'Resource Locks', concept: 'CanNotDelete or ReadOnly locks that override RBAC.', purpose: 'Protect critical resources from accidental deletion.', arch: 'Inherited by child resources. ReadOnly can break operations that need a POST (listing keys, scaling).', tf: 'azurerm_management_lock.', example: 'resource "azurerm_management_lock" "rg" {\n  name       = "do-not-delete"\n  scope      = azurerm_resource_group.main.id\n  lock_level = "CanNotDelete"\n}', mistakes: ['ReadOnly locks on resource groups with storage or App Service.', 'Forgetting that terraform destroy needs the lock removed first.'], ms: MS + 'azure-resource-manager/management/lock-resources', reg: ['azurerm_management_lock'] },
  { t: 'Networking', concept: 'Hub-and-spoke or Virtual WAN topology with central egress, hybrid connectivity and private DNS.', purpose: 'Consistent, inspectable connectivity for every landing zone.', arch: 'Hub VNet (firewall, Bastion, gateways) in the connectivity subscription; spokes peered to it; private DNS zones linked centrally.', tf: 'azurerm_virtual_network, azurerm_virtual_network_peering, azurerm_firewall, azurerm_private_dns_zone_virtual_network_link.', example: 'Hub 10.100.0.0/16 <-> Spoke 10.0.0.0/16\n0.0.0.0/0 -> Azure Firewall', mistakes: ['Overlapping address spaces between spokes.', 'Expecting peering to be transitive.'], ms: MS + 'architecture/networking/architecture/hub-spoke', reg: ['azurerm_virtual_network_peering', 'azurerm_firewall'] },
  { t: 'Security', concept: 'Defence in depth: identity, network, data and posture management.', purpose: 'Reduce attack surface and detect threats early.', arch: 'Entra ID and PIM, private endpoints, Defender for Cloud, the Microsoft cloud security benchmark initiative.', tf: 'Policy assignments for MCSB, private endpoints, managed identities, no secrets in code.', example: 'data "azurerm_policy_set_definition" "mcsb" {\n  name = "1f3afdf9-d0c9-4c3d-847f-89da613e70a8"\n}', mistakes: ['Long-lived client secrets for pipelines (use OIDC).', 'Public endpoints left on after adding private endpoints.'], ms: MS + 'security/fundamentals/overview', reg: ['azurerm_private_endpoint'] },
  { t: 'Monitoring', concept: 'Central logging and alerting for platform and workloads.', purpose: 'See everything in one place and react quickly.', arch: 'A Log Analytics workspace in the management subscription; diagnostic settings and the Activity Log from every subscription.', tf: 'azurerm_log_analytics_workspace, azurerm_monitor_diagnostic_setting, azurerm_monitor_action_group, alerts.', example: 'resource "azurerm_monitor_diagnostic_setting" "activity" {\n  target_resource_id = data.azurerm_subscription.current.id\n  ...\n}', mistakes: ['A workspace per application, so nobody can correlate.', 'Collecting everything at Debug level and paying for it.'], ms: MS + 'azure-monitor/fundamentals/overview', reg: ['azurerm_log_analytics_workspace', 'azurerm_monitor_diagnostic_setting'] },
  { t: 'Cost Management', concept: 'Budgets, tags and reviews that keep spend predictable.', purpose: 'Catch overspend early and allocate cost to owners.', arch: 'Budgets at subscription or resource group scope, alerting an action group; tags for chargeback.', tf: 'azurerm_consumption_budget_subscription, azurerm_consumption_budget_resource_group.', example: 'resource "azurerm_consumption_budget_subscription" "monthly" {\n  amount     = 500\n  time_grain = "Monthly"\n  ...\n}', mistakes: ['Treating a budget as a hard cap. It only alerts.', 'Budgets nobody receives.'], ms: MS + 'cost-management-billing/costs/tutorial-acm-create-budgets', reg: ['azurerm_consumption_budget_subscription'] },
];

